INSERT INTO `dashboard_widgets` VALUES (9,'Total Items Sold','SELECT IFNULL(SUM(qty),0) FROM all_sale_detail WHERE sale_or_return=\'SALE VOUCHER\'','SELECT item_name, SUM(qty) as total_qty \r\n FROM all_sale_detail \r\n WHERE sale_or_return=\'SALE VOUCHER\'\r\n GROUP BY item_name\r\n ORDER BY total_qty DESC\r\n LIMIT 20',1),(10,'Total Sales (Rs)','SELECT IFNULL(SUM(t.total_amount),0) FROM (\r\n     SELECT voucher_no, MAX(total_amount) as total_amount\r\n     FROM all_sale_detail\r\n     WHERE sale_or_return=\'SALE VOUCHER\'\r\n     GROUP BY voucher_no\r\n) t','SELECT voucher_no, account_description, MAX(total_amount) as total_amount\r\n FROM all_sale_detail\r\n WHERE sale_or_return=\'SALE VOUCHER\'\r\n GROUP BY voucher_no\r\n ORDER BY voucher_no DESC\r\n LIMIT 50',1),(11,'Top 5 Items','SELECT COUNT(DISTINCT item_code) FROM all_sale_detail WHERE sale_or_return=\'SALE VOUCHER\'','SELECT item_name, SUM(qty) as total_qty\r\n FROM all_sale_detail\r\n WHERE sale_or_return=\'SALE VOUCHER\'\r\n GROUP BY item_name\r\n ORDER BY total_qty DESC\r\n LIMIT 5',1),(12,'Total Sale Vouchers','SELECT COUNT(DISTINCT voucher_no) FROM all_sale_detail WHERE sale_or_return=\'SALE VOUCHER\'','SELECT voucher_no, MAX(total_amount) as total_amount\r\n FROM all_sale_detail\r\n WHERE sale_or_return=\'SALE VOUCHER\'\r\n GROUP BY voucher_no\r\n ORDER BY voucher_no DESC\r\n LIMIT 50',1),(13,'Total Sale Return Vouchers','SELECT COUNT(DISTINCT voucher_no) FROM all_sale_detail WHERE sale_or_return=\'SALE RETURN\'','SELECT voucher_no, MAX(total_amount) as total_amount\r\n FROM all_sale_detail\r\n WHERE sale_or_return=\'SALE RETURN\'\r\n GROUP BY voucher_no\r\n ORDER BY voucher_no DESC\r\n LIMIT 50',1),(15,'Today Sale','\r\nSELECT IFNULL(SUM(t.total_amount),0)\r\nFROM (\r\n    SELECT voucher_no, MAX(total_amount) as total_amount\r\n    FROM all_sale_detail\r\n    WHERE sale_or_return=\'SALE VOUCHER\'\r\n    AND DATE(record_date)=CURDATE()\r\n    GROUP BY voucher_no\r\n) t\r\n','\r\nSELECT voucher_no, account_description, MAX(total_amount) as total_amount\r\nFROM all_sale_detail\r\nWHERE sale_or_return=\'SALE VOUCHER\'\r\nAND DATE(record_date)=CURDATE()\r\nGROUP BY voucher_no\r\nORDER BY voucher_no DESC\r\n',1),(16,'Last 7 Days Sale','\r\nSELECT IFNULL(SUM(t.total_amount),0)\r\nFROM (\r\n    SELECT voucher_no, MAX(total_amount) as total_amount\r\n    FROM all_sale_detail\r\n    WHERE sale_or_return=\'SALE VOUCHER\'\r\n    AND record_date >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)\r\n    GROUP BY voucher_no\r\n) t\r\n','\r\nSELECT voucher_no, account_description, MAX(total_amount) as total_amount\r\nFROM all_sale_detail\r\nWHERE sale_or_return=\'SALE VOUCHER\'\r\nAND record_date >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)\r\nGROUP BY voucher_no\r\nORDER BY voucher_no DESC\r\n',1),(17,'Last Month Sale','\r\nSELECT IFNULL(SUM(t.total_amount),0)\r\nFROM (\r\n    SELECT voucher_no, MAX(total_amount) as total_amount\r\n    FROM all_sale_detail\r\n    WHERE sale_or_return=\'SALE VOUCHER\'\r\n    AND MONTH(record_date)=MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))\r\n    AND YEAR(record_date)=YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))\r\n    GROUP BY voucher_no\r\n) t\r\n','\r\nSELECT voucher_no, account_description, MAX(total_amount) as total_amount\r\nFROM all_sale_detail\r\nWHERE sale_or_return=\'SALE VOUCHER\'\r\nAND MONTH(record_date)=MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))\r\nAND YEAR(record_date)=YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))\r\nGROUP BY voucher_no\r\nORDER BY voucher_no DESC\r\n',1),(18,'Top 5 Clients (All Time)','\r\nSELECT COUNT(DISTINCT account_no)\r\nFROM all_sale_detail\r\nWHERE sale_or_return=\'SALE VOUCHER\'\r\n','\r\nSELECT account_no, account_description, SUM(voucher_total) as total_sale\r\nFROM (\r\n    SELECT voucher_no, account_no, account_description,\r\n           MAX(total_amount) as voucher_total\r\n    FROM all_sale_detail\r\n    WHERE sale_or_return=\'SALE VOUCHER\'\r\n    GROUP BY voucher_no\r\n) t\r\nGROUP BY account_no\r\nORDER BY total_sale DESC\r\nLIMIT 5\r\n',1),(19,'Top 5 Clients (This Month)','\r\nSELECT COUNT(DISTINCT account_no)\r\nFROM all_sale_detail\r\nWHERE sale_or_return=\'SALE VOUCHER\'\r\nAND MONTH(record_date)=MONTH(CURDATE())\r\nAND YEAR(record_date)=YEAR(CURDATE())\r\n','\r\nSELECT account_no, account_description, SUM(voucher_total) as total_sale\r\nFROM (\r\n    SELECT voucher_no, account_no, account_description,\r\n           MAX(total_amount) as voucher_total\r\n    FROM all_sale_detail\r\n    WHERE sale_or_return=\'SALE VOUCHER\'\r\n    AND MONTH(record_date)=MONTH(CURDATE())\r\n    AND YEAR(record_date)=YEAR(CURDATE())\r\n    GROUP BY voucher_no\r\n) t\r\nGROUP BY account_no\r\nORDER BY total_sale DESC\r\nLIMIT 5\r\n',1),(20,'Top 5 Clients (Last 30 Days)','\r\nSELECT COUNT(DISTINCT account_no)\r\nFROM all_sale_detail\r\nWHERE sale_or_return=\'SALE VOUCHER\'\r\nAND record_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)\r\n','\r\nSELECT account_no, account_description, SUM(voucher_total) as total_sale\r\nFROM (\r\n    SELECT voucher_no, account_no, account_description,\r\n           MAX(total_amount) as voucher_total\r\n    FROM all_sale_detail\r\n    WHERE sale_or_return=\'SALE VOUCHER\'\r\n    AND record_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)\r\n    GROUP BY voucher_no\r\n) t\r\nGROUP BY account_no\r\nORDER BY total_sale DESC\r\nLIMIT 5\r\n',1),(22,'Highest Credit Customer','\r\nSELECT COUNT(DISTINCT account_no)\r\nFROM all_sale_detail\r\nWHERE sale_or_return=\'SALE VOUCHER\'\r\n','\r\nSELECT account_no, account_description,\r\n       SUM(voucher_credit) as total_credit\r\nFROM (\r\n    SELECT voucher_no, account_no, account_description,\r\n           MAX(total_amount - cash_received) as voucher_credit\r\n    FROM all_sale_detail\r\n    WHERE sale_or_return=\'SALE VOUCHER\'\r\n    GROUP BY voucher_no\r\n) t\r\nGROUP BY account_no\r\nHAVING total_credit > 0\r\nORDER BY total_credit DESC\r\nLIMIT 5\r\n',1),(23,'Total Purchase (Rs)','\r\nSELECT IFNULL(SUM(t.voucher_total),0)\r\nFROM (\r\n    SELECT voucher_no, MAX(voucher_total) as voucher_total\r\n    FROM all_purchase_detail\r\n    WHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n    GROUP BY voucher_no\r\n) t\r\n','\r\nSELECT voucher_no, account_description, MAX(voucher_total) as voucher_total\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE VOUCHER\'\r\nGROUP BY voucher_no\r\nORDER BY voucher_no DESC\r\nLIMIT 50\r\n',1),(24,'Today Purchase','\r\nSELECT IFNULL(SUM(t.voucher_total),0)\r\nFROM (\r\n    SELECT voucher_no, MAX(voucher_total) as voucher_total\r\n    FROM all_purchase_detail\r\n    WHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n    AND DATE(record_date)=CURDATE()\r\n    GROUP BY voucher_no\r\n) t\r\n','\r\nSELECT voucher_no, account_description, MAX(voucher_total) as voucher_total\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE VOUCHER\'\r\nAND DATE(record_date)=CURDATE()\r\nGROUP BY voucher_no\r\nORDER BY voucher_no DESC\r\n',1),(25,'Last 7 Days Purchase','\r\nSELECT IFNULL(SUM(t.voucher_total),0)\r\nFROM (\r\n    SELECT voucher_no, MAX(voucher_total) as voucher_total\r\n    FROM all_purchase_detail\r\n    WHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n    AND record_date >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)\r\n    GROUP BY voucher_no\r\n) t\r\n','\r\nSELECT voucher_no, account_description, MAX(voucher_total) as voucher_total\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE VOUCHER\'\r\nAND record_date >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)\r\nGROUP BY voucher_no\r\nORDER BY voucher_no DESC\r\n',1),(26,'Last Month Purchase','\r\nSELECT IFNULL(SUM(t.voucher_total),0)\r\nFROM (\r\n    SELECT voucher_no, MAX(voucher_total) as voucher_total\r\n    FROM all_purchase_detail\r\n    WHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n    AND MONTH(record_date)=MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))\r\n    AND YEAR(record_date)=YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))\r\n    GROUP BY voucher_no\r\n) t\r\n','\r\nSELECT voucher_no, account_description, MAX(voucher_total) as voucher_total\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE VOUCHER\'\r\nAND MONTH(record_date)=MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))\r\nAND YEAR(record_date)=YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))\r\nGROUP BY voucher_no\r\nORDER BY voucher_no DESC\r\n',1),(27,'Total Purchase Vouchers','\r\nSELECT COUNT(DISTINCT voucher_no)\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n','\r\nSELECT voucher_no, MAX(voucher_total) as voucher_total\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE VOUCHER\'\r\nGROUP BY voucher_no\r\nORDER BY voucher_no DESC\r\nLIMIT 50\r\n',1),(28,'Total Purchase Return Vouchers','\r\nSELECT COUNT(DISTINCT voucher_no)\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE RETURN\'\r\n','\r\nSELECT voucher_no, MAX(voucher_total) as voucher_total\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE RETURN\'\r\nGROUP BY voucher_no\r\nORDER BY voucher_no DESC\r\nLIMIT 50\r\n',1),(29,'Top 5 Purchased Items','\r\nSELECT COUNT(DISTINCT item_code)\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n','\r\nSELECT item_name, SUM(qty) as total_qty\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE VOUCHER\'\r\nGROUP BY item_name\r\nORDER BY total_qty DESC\r\nLIMIT 5\r\n',1),(30,'Top 5 Suppliers','\r\nSELECT COUNT(DISTINCT account_no)\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n','\r\nSELECT account_no, account_description,\r\n       SUM(voucher_total) as total_purchase\r\nFROM (\r\n    SELECT voucher_no, account_no, account_description,\r\n           MAX(voucher_total) as voucher_total\r\n    FROM all_purchase_detail\r\n    WHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n    GROUP BY voucher_no\r\n) t\r\nGROUP BY account_no\r\nORDER BY total_purchase DESC\r\nLIMIT 5\r\n',1),(31,'Purchase Growth %','\r\nSELECT COUNT(DISTINCT account_no)\r\nFROM all_purchase_detail\r\nWHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n','\r\nSELECT \r\n    curr.account_no,\r\n    curr.this_month,\r\n    prev.last_month,\r\n    ROUND(\r\n        ((curr.this_month - IFNULL(prev.last_month,0))\r\n        / NULLIF(prev.last_month,0)) * 100, 2\r\n    ) as growth_percent\r\nFROM\r\n(\r\n    SELECT account_no,\r\n           SUM(voucher_total) as this_month\r\n    FROM (\r\n        SELECT voucher_no, account_no,\r\n               MAX(voucher_total) as voucher_total\r\n        FROM all_purchase_detail\r\n        WHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n        AND MONTH(record_date)=MONTH(CURDATE())\r\n        AND YEAR(record_date)=YEAR(CURDATE())\r\n        GROUP BY voucher_no\r\n    ) t\r\n    GROUP BY account_no\r\n) curr\r\nLEFT JOIN\r\n(\r\n    SELECT account_no,\r\n           SUM(voucher_total) as last_month\r\n    FROM (\r\n        SELECT voucher_no, account_no,\r\n               MAX(voucher_total) as voucher_total\r\n        FROM all_purchase_detail\r\n        WHERE issue_or_return=\'PURCHASE VOUCHER\'\r\n        AND MONTH(record_date)=MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))\r\n        AND YEAR(record_date)=YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))\r\n        GROUP BY voucher_no\r\n    ) t\r\n    GROUP BY account_no\r\n) prev\r\nON curr.account_no = prev.account_no\r\nWHERE prev.last_month IS NOT NULL\r\nORDER BY growth_percent DESC\r\nLIMIT 5\r\n',1),(32,'Total Inventory Items','SELECT COUNT(*) FROM all_inventory','SELECT item_code, item_name, main_category FROM all_inventory LIMIT 100',1),(33,'Low Stock Items','\r\nSELECT COUNT(*)\r\nFROM all_inventory\r\nWHERE min_stock > 0 AND min_stock >= max_stock\r\n','\r\nSELECT item_code, item_name, min_stock, max_stock\r\nFROM all_inventory\r\nWHERE min_stock > 0 AND min_stock >= max_stock\r\nORDER BY min_stock DESC\r\n',1),(34,'Out of Stock Items','\r\nSELECT COUNT(*)\r\nFROM all_inventory\r\nWHERE min_stock = 0\r\n','\r\nSELECT item_code, item_name, min_stock\r\nFROM all_inventory\r\nWHERE min_stock = 0\r\n',1),(35,'Overstock Items','\r\nSELECT COUNT(*)\r\nFROM all_inventory\r\nWHERE max_stock > 50\r\n','\r\nSELECT item_code, item_name, max_stock\r\nFROM all_inventory\r\nWHERE max_stock > 50\r\nORDER BY max_stock DESC\r\nLIMIT 50\r\n',1),(36,'Top 5 Retail Profit Items','\r\nSELECT COUNT(*)\r\nFROM all_inventory\r\nWHERE retail_profit > 0\r\n','\r\nSELECT item_code, item_name, retail_profit\r\nFROM all_inventory\r\nORDER BY retail_profit DESC\r\nLIMIT 5\r\n',1),(37,'Top 5 Highest Purchase Rate','\r\nSELECT COUNT(*)\r\nFROM all_inventory\r\n','\r\nSELECT item_code, item_name, purchase_rate\r\nFROM all_inventory\r\nORDER BY purchase_rate DESC\r\nLIMIT 5\r\n',1),(38,'Category Wise Items','\r\nSELECT COUNT(DISTINCT main_category)\r\nFROM all_inventory\r\n','\r\nSELECT main_category, COUNT(*) as total_items\r\nFROM all_inventory\r\nGROUP BY main_category\r\nORDER BY total_items DESC\r\n',1),(39,'Total Potential Retail Profit','\r\nSELECT IFNULL(SUM(retail_profit),0)\r\nFROM all_inventory\r\n','\r\nSELECT item_code, item_name, retail_profit\r\nFROM all_inventory\r\nORDER BY retail_profit DESC\r\nLIMIT 20\r\n',1);
