CREATE TABLE `inventory` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `main_category` varchar(80) NOT NULL,
  `item_code` varchar(30) NOT NULL,
  `item_name` varchar(200) DEFAULT NULL,
  `min_stock` int(11) DEFAULT NULL,
  `max_stock` int(11) DEFAULT NULL,
  `stock_account` varchar(15) NOT NULL,
  `revenue_account` varchar(15) NOT NULL,
  `expense_account` varchar(15) NOT NULL,
  `purchase_rate` decimal(15,2) DEFAULT NULL,
  `whole_sale_rate` decimal(15,2) DEFAULT NULL,
  `retail_rate` decimal(15,2) DEFAULT NULL,
  `record_date` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `inventory_unique` (`item_code`,`main_category`)
) ENGINE=InnoDB AUTO_INCREMENT=894 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
