DROP TABLE IF EXISTS `online_general_voucher`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `online_general_voucher` (
  `VOUCHER_NO` int(11) NOT NULL AUTO_INCREMENT,
  `VOUCHER_TYPE` enum('JV','OTHER') NOT NULL DEFAULT 'JV',
  `VOUCHER_DATE` date NOT NULL,
  `TOTAL_DEBIT` decimal(15,2) NOT NULL DEFAULT 0.00,
  `TOTAL_CREDIT` decimal(15,2) NOT NULL DEFAULT 0.00,
  `NARRATION` text DEFAULT NULL,
  `CREATED_BY` int(11) DEFAULT NULL,
  `CREATED_AT` timestamp NOT NULL DEFAULT current_timestamp(),
  `UPDATED_AT` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  `STATUS` tinyint(4) DEFAULT 1,
  `financial_year_id` int(11) DEFAULT NULL,
  `series_no` int(11) DEFAULT NULL,
  `display_voucher_no` varchar(50) DEFAULT NULL,
  `approval_status` varchar(20) NOT NULL DEFAULT 'Draft',
  `approved_at` datetime DEFAULT NULL,
  `APPROVED_BY` int(11) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`VOUCHER_NO`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

